package main
import("encoding/json";"log/slog";"net/http";"os";"time")
type Product struct{ID string `json:"id"`;Name string `json:"name"`;Price int `json:"price"`;Currency string `json:"currency"`;Emoji string `json:"emoji"`}
var products=[]Product{{"mug","Incident Response Mug",1800,"USD","☕"},{"notebook","Runbook Notebook",1200,"USD","📓"},{"shirt","Ship It T-Shirt",2900,"USD","👕"},{"keyboard","Deploy Keyboard",7900,"USD","⌨️"}}
func reply(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_=json.NewEncoder(w).Encode(v)}
func handler() http.Handler{m:=http.NewServeMux();for _,p:=range []string{"/health/live","/health/ready"}{m.HandleFunc("GET "+p,func(w http.ResponseWriter,r *http.Request){reply(w,200,map[string]string{"status":"ok"})})};m.HandleFunc("GET /products",func(w http.ResponseWriter,r *http.Request){reply(w,200,products)});m.HandleFunc("GET /products/{id}",func(w http.ResponseWriter,r *http.Request){for _,p:=range products{if p.ID==r.PathValue("id"){reply(w,200,p);return}};reply(w,404,map[string]string{"error":"product_not_found"})});m.HandleFunc("GET /metrics",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/plain; version=0.0.4");_,_=w.Write([]byte("# TYPE boutique_catalogue_up gauge\nboutique_catalogue_up 1\n"))});return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){t:=time.Now();m.ServeHTTP(w,r);slog.Info("request","method",r.Method,"path",r.URL.Path,"duration_ms",time.Since(t).Milliseconds(),"request_id",r.Header.Get("X-Request-ID"))})}
func main(){slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout,nil)));s:=http.Server{Addr:":8081",Handler:handler(),ReadHeaderTimeout:5*time.Second,ReadTimeout:10*time.Second,WriteTimeout:10*time.Second,IdleTimeout:60*time.Second};if err:=s.ListenAndServe();err!=nil{slog.Error("server","error",err);os.Exit(1)}}
